CREATE OR REPLACE VIEW god2_research.vw_xjz_npc_dialog_text_cleanup_zh_tw AS
SELECT
    COUNT(*) AS remaining_suspected_simplified_text_rows,
    'NPC 對話與任務文字' AS game_function_zh_tw,
    'text_zh_tw 與 speaker_or_branch_zh_tw 已套用繁中清理；正式 NPC appearance 名稱同步清理。' AS cleanup_status_zh_tw,
    UTC_TIMESTAMP() AS generated_at_utc
FROM god2_research.xjz_npc_dialog_candidates
WHERE text_zh_tw LIKE '%传%' OR text_zh_tw LIKE '%转%' OR text_zh_tw LIKE '%华%' OR text_zh_tw LIKE '%龙%' OR text_zh_tw LIKE '%气%' OR text_zh_tw LIKE '%宠%' OR text_zh_tw LIKE '%学%' OR text_zh_tw LIKE '%习%' OR text_zh_tw LIKE '%双%' OR text_zh_tw LIKE '%无%' OR text_zh_tw LIKE '%级%' OR text_zh_tw LIKE '%药%' OR text_zh_tw LIKE '%装%' OR text_zh_tw LIKE '%发%' OR text_zh_tw LIKE '%击%' OR text_zh_tw LIKE '%术%' OR text_zh_tw LIKE '%圣%' OR text_zh_tw LIKE '%势%' OR text_zh_tw LIKE '%炼%' OR text_zh_tw LIKE '%宝%' OR text_zh_tw LIKE '%飞%' OR text_zh_tw LIKE '%门%' OR text_zh_tw LIKE '%队%' OR text_zh_tw LIKE '%阵%' OR text_zh_tw LIKE '%类%' OR text_zh_tw LIKE '%数%' OR text_zh_tw LIKE '%复%' OR text_zh_tw LIKE '%态%' OR text_zh_tw LIKE '%证%' OR text_zh_tw LIKE '%据%' OR text_zh_tw LIKE '%补%' OR text_zh_tw LIKE '%齐%' OR text_zh_tw LIKE '%触%' OR text_zh_tw LIKE '%优%' OR text_zh_tw LIKE '%实%' OR text_zh_tw LIKE '%图%' OR text_zh_tw LIKE '%观%' OR text_zh_tw LIKE '%师%' OR text_zh_tw LIKE '%开%' OR text_zh_tw LIKE '%关%' OR text_zh_tw LIKE '%运%' OR text_zh_tw LIKE '%维%' OR text_zh_tw LIKE '%启%' OR text_zh_tw LIKE '%归%' OR text_zh_tw LIKE '%线%' OR text_zh_tw LIKE '%须%' OR text_zh_tw LIKE '%简%' OR text_zh_tw LIKE '%还%' OR text_zh_tw LIKE '%说%' OR text_zh_tw LIKE '%货%' OR text_zh_tw LIKE '%镇%' OR text_zh_tw LIKE '%觉%' OR text_zh_tw LIKE '%头%' OR text_zh_tw LIKE '%询%' OR text_zh_tw LIKE '%将%' OR text_zh_tw LIKE '%东%' OR text_zh_tw LIKE '%调%' OR text_zh_tw LIKE '%踪%' OR text_zh_tw LIKE '%迹%' OR text_zh_tw LIKE '%虽%' OR text_zh_tw LIKE '%并%' OR text_zh_tw LIKE '%却%' OR text_zh_tw LIKE '%视%' OR text_zh_tw LIKE '%马%' OR text_zh_tw LIKE '%于%' OR text_zh_tw LIKE '%该%' OR text_zh_tw LIKE '%这%' OR text_zh_tw LIKE '%诉%' OR text_zh_tw LIKE '%们%' OR text_zh_tw LIKE '%缘%' OR text_zh_tw LIKE '%动%' OR text_zh_tw LIKE '%宫%' OR text_zh_tw LIKE '%楼%' OR text_zh_tw LIKE '%潜%' OR text_zh_tw LIKE '%让%' OR text_zh_tw LIKE '%离%' OR text_zh_tw LIKE '%烦%' OR text_zh_tw LIKE '%强%' OR text_zh_tw LIKE '%黄%' OR text_zh_tw LIKE '%顶